import {
  Mesh,
  PlaneGeometry,
  Group,
  Vector3,
  Euler,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  // Root container
  const root = new Group();

  // Apply scene placement
  const pos = config.position ?? { x: 0, y: 0, z: 0 };
  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.scale ?? { x: 1, y: 1, z: 1 };

  root.position.set(pos.x, pos.y, pos.z);
  root.rotation.set(rot.x, rot.y, rot.z);
  root.scale.set(scl.x, scl.y, scl.z);

  // ---------- Background Plane ----------
  const bgTexture = ctx.textureLoader.load(
    '/prism-assets/chrome/brushed-metal.map.png'
  );

  const bgMaterial = new MeshBasicNodeMaterial({
    map: texture(bgTexture),
    toneMapped: true,
  });

  const bgGeometry = new PlaneGeometry(1, 1);
  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  bgMesh.position.set(0, 0, 0);
  root.add(bgMesh);

  // ---------- Text Mesh ----------
  // Expected config shape for text
  const textContent = (config.textContent && config.textContent[0]) || 'Collection 2';
  const inkColor = (config.colors && config.colors.ink) || '#16161d';

  const textMesh = createTextMesh({
    text: textContent,
    fontAtlas: ctx.fontAtlas,
    atlasRegion: { x: 0, y: 0, width: 512, height: 320 },
    color: inkColor,
    // Choose a size that roughly matches the headline type scale
    // (scene‑unit em height ≈ 0.34). We scale the plane accordingly.
    size: 0.34,
    // Align centered
    anchorX: 0.5,
    anchorY: 0.5,
    // Slightly in front of the background plane
    offsetZ: 0.001,
  });

  root.add(textMesh);

  // ---------- Apply cinematic primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // ---------- Event handlers placeholder ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = []; // store any GSAP timelines we may create later

  root.userData.cleanup = () => {
    // Dispose geometries and materials
    bgGeometry.dispose();
    bgMaterial.dispose();
    // Dispose texture if it is not shared (optional, guard against double‑dispose)
    if (bgTexture && bgTexture.isTexture) {
      bgTexture.dispose();
    }

    // Cleanup text mesh (expects it to expose a dispose method)
    if (textMesh && typeof textMesh.userData?.cleanup === 'function') {
      textMesh.userData.cleanup();
    } else if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }

    // Kill any GSAP timelines
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
  };

  return root;
}
